// Look up the Leads row whose Approval Slack TS matches the event's ts.
// All routing context (gmail thread id, lead email/name, subject,
// pending Claude draft) lives on this row -- no Slack metadata needed.
const items = ((($json.data || {}).items_page_by_column_values) || {}).items || [];
const lookup = $('Build Monday Lookup').item.json;
if (!items.length) {
  // No matching pending approval (already handled, or stale event). Drop.
  return [];
}
const lead = items[0];
function colVal(item, colId) { const c = (item.column_values || []).find(c => c.id === colId); return c ? (c.text || '') : ''; }
const leadName = colVal(lead, $env.MONDAY_COL_LEAD_NAME) || lead.name;
const leadEmail = colVal(lead, $env.MONDAY_COL_LEAD_EMAIL);
return [{ json: {
  route: lookup._route,
  edited_text: lookup._edited_text || '',
  leads_item_id: lead.id,
  lead_name: leadName,
  lead_email: leadEmail,
  // sender_* aliases preserved for downstream nodes that already reference them
  sender_name: leadName,
  sender_email: leadEmail,
  gmail_thread_id: colVal(lead, $env.MONDAY_COL_LEAD_THREAD_ID),
  subject: colVal(lead, $env.MONDAY_COL_LEAD_SUBJECT_LINE),
  claude_draft: colVal(lead, $env.MONDAY_COL_LEAD_PENDING_DRAFT),
  channel: lookup._channel,
  approval_ts: lookup._target_ts
}}];

